fn run_runtime_implementation_interface_validation() -> Result<JsonValue> {
    let checker = lean_proofgrade_runtime_implementation_interface_checker_path()?;
    let interface = runtime_implementation_interface_artifact()?;
    let source_paths = runtime_implementation_interface_source_paths();
    let (interface_path, interface_json_bytes) =
        write_temp_json("runtime-implementation-interface", &interface)?;
    let output = Command::new(&checker).arg(&interface_path).output()?;
    let _ = fs::remove_file(&interface_path);
    if !output.status.success() {
        return Err(anyhow!(
            "Lean runtime implementation interface validation failed: {}",
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    Ok(json!({
        "checker": display_report_path(&checker),
        "source_files": existing_report_paths(&source_paths),
        "source_bytes": runtime_implementation_interface_source_bytes(&interface),
        "handwritten_runtime_public_only_theorem_checked": true,
        "public_shell_rejects_confidential_expression_evaluation_theorem_checked": true,
        "public_shell_canonical_hashing_guarded_by_public_entry_theorem_checked": true,
        "handwritten_runtime_lacks_direct_secret_ops_theorem_checked": true,
        "handwritten_host_coordination_lacks_secret_serialization_theorem_checked": true,
        "runtime_host_visible_error_taxonomy_theorem_checked": true,
        "artifact_json_bytes": interface_json_bytes,
        "lean_checker_kind": "runtime implementation interface",
        "lean_checker_input": "source-backed runtime implementation interface",
        "evidence_classification": "source-frozen/static-drift checked",
        "rust_semantic_refinement_claimed": false,
        "source_text_predicate_boundary": true,
        "deeper_semantics_of_rust_refinement_required": true,
        "lean_stdout": String::from_utf8_lossy(&output.stdout).trim(),
        "accepted": true,
    }))
}

