fn validate_runtime_kernel_machine_finish_witness_case(
    name: &'static str,
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    target: &CallSpec,
    checker: &Path,
) -> Result<JsonValue> {
    let trace = run_target_call(artifact, setup, target.entrypoint, target.args.clone())?;
    let runtime_witness = trace.runtime_refinement_witness()?;
    let exact_kernel_witness =
        exact_confidential_kernel_witness(&trace, artifact, target.entrypoint)?;
    if runtime_witness.kernel_witness() != exact_kernel_witness.as_ref() {
        return Err(anyhow!(
            "runtime refinement witness for {} does not preserve the exact kernel witness",
            name
        ));
    }
    let exact_runtime_kernel_refinement_witness =
        trace.exact_runtime_kernel_refinement_witness()?;
    if runtime_witness.runtime_kernel_refinement_witness()
        != Some(&exact_runtime_kernel_refinement_witness)
    {
        return Err(anyhow!(
            "runtime refinement witness for {} does not preserve the runtime phase witness",
            name
        ));
    }
    let runtime_kernel_machine_finish_witness =
        trace.exact_runtime_kernel_machine_finish_witness().map_err(|err| {
            anyhow!(
                "execution trace for {} did not expose an exact runtime kernel machine finish witness: {}",
                name,
                err
            )
        })?;
    let finish_bundle = trace.exact_runtime_kernel_finish_bundle().map_err(|err| {
        anyhow!(
            "execution trace for {} did not expose an exact runtime kernel finish bundle: {}",
            name,
            err
        )
    })?;
    if runtime_kernel_machine_finish_witness.projected_finish_bundle() != finish_bundle {
        return Err(anyhow!(
            "runtime kernel machine finish witness for {} does not preserve the exact runtime kernel finish bundle",
            name
        ));
    }

    let machine_finish_witness_json_bytes =
        serde_json::to_vec(&runtime_kernel_machine_finish_witness)?.len();
    let projected_finish_bundle_json_bytes = serde_json::to_vec(&finish_bundle)?.len();
    let (witness_path, witness_file_bytes) =
        write_temp_json(name, &runtime_kernel_machine_finish_witness)?;
    let output = Command::new(checker).arg(&witness_path).output()?;
    if !output.status.success() {
        return Err(anyhow!(
            "Lean runtime kernel machine finish witness validation failed for {}: {} (artifact preserved at {})",
            name,
            String::from_utf8_lossy(&output.stderr).trim(),
            witness_path.display()
        ));
    }
    let _ = fs::remove_file(&witness_path);

    Ok(json!({
        "scenario": name,
        "entrypoint": target.entrypoint,
        "setup_calls": setup.len(),
        "gas_used": trace.gas_used,
        "boundary_events": runtime_witness.boundary_schedule().len(),
        "kernel_witness": kernel_witness_summary(exact_kernel_witness.as_ref()),
        "runtime_kernel_refinement_witness": runtime_kernel_refinement_witness_summary(
            runtime_witness.runtime_kernel_refinement_witness(),
            exact_kernel_witness.as_ref(),
        ),
        "runtime_kernel_machine_finish_witness": {
            "entrypoint_id": finish_bundle.entrypoint_id(),
            "expected_kernel_step_count": finish_bundle
                .expected_kernel_steps()
                .map_or(0, |steps| steps.len()),
            "emitted_kernel_step_count": finish_bundle.kernel_steps().len(),
            "expected_kernel_step_index":
                runtime_kernel_machine_finish_witness.expected_kernel_step_index(),
            "max_kernel_ops": runtime_kernel_machine_finish_witness.max_kernel_ops(),
            "max_runtime_phase_event_count":
                runtime_kernel_machine_finish_witness.max_runtime_phase_event_count(),
            "runtime_phase_prefix_event_count":
                finish_bundle.runtime_phase_events_before_finish().len(),
            "public_object_universe": finish_bundle.public_object_ids(),
            "resource_event_count": finish_bundle.resource_events().len(),
        },
        "machine_finish_witness_json_bytes": machine_finish_witness_json_bytes,
        "projected_finish_bundle_json_bytes": projected_finish_bundle_json_bytes,
        "witness_file_bytes": witness_file_bytes,
        "lean_checker_kind": "runtime kernel machine finish witness",
        "lean_checker_input": "runtime kernel machine finish witness",
        "lean_stdout": String::from_utf8_lossy(&output.stdout).trim(),
        "accepted": true,
    }))
}

fn validate_runtime_implementation_confinement_boundary_case(
    name: &'static str,
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    target: &CallSpec,
    checker: &Path,
    implementation_interface: &ImportedRuntimeImplementationInterface,
) -> Result<JsonValue> {
    let trace = run_target_call(artifact, setup, target.entrypoint, target.args.clone())?;
    let witness = trace.runtime_refinement_witness()?;
    let kernel_interface_bundle = trace.runtime_kernel_interface_bundle(artifact)?;
    let exact_kernel_witness =
        exact_confidential_kernel_witness(&trace, artifact, target.entrypoint)?;
    if witness.kernel_witness() != exact_kernel_witness.as_ref() {
        return Err(anyhow!(
            "runtime refinement witness for {} does not preserve the exact kernel witness",
            name
        ));
    }
    if kernel_interface_bundle.kernel_witness() != exact_kernel_witness.as_ref().unwrap() {
        return Err(anyhow!(
            "runtime implementation confinement boundary for {} does not preserve the exact kernel witness",
            name
        ));
    }
    let exact_runtime_kernel_refinement_witness =
        trace.exact_runtime_kernel_refinement_witness()?;
    if witness.runtime_kernel_refinement_witness() != Some(&exact_runtime_kernel_refinement_witness)
    {
        return Err(anyhow!(
            "runtime refinement witness for {} does not preserve the runtime phase witness",
            name
        ));
    }
    if kernel_interface_bundle.expected_kernel_steps()
        != kernel_interface_bundle.kernel_witness().kernel_steps()
    {
        return Err(anyhow!(
            "runtime implementation confinement boundary for {} does not preserve the exact expected kernel steps",
            name
        ));
    }
    if kernel_interface_bundle.expected_public_object_ids()
        != kernel_interface_bundle
            .kernel_witness()
            .expected_public_object_schedule()
            .as_deref()
            .unwrap_or(&[])
    {
        return Err(anyhow!(
            "runtime implementation confinement boundary for {} does not preserve the exact expected public object universe",
            name
        ));
    }
    if kernel_interface_bundle.expected_kernel_schedule()
        != &kernel_interface_bundle
            .kernel_witness()
            .emitted_kernel_schedule()
    {
        return Err(anyhow!(
            "runtime implementation confinement boundary for {} does not preserve the exact expected kernel schedule",
            name
        ));
    }
    let boundary = ImportedRuntimeImplementationConfinementBoundary {
        implementation_interface: implementation_interface.clone(),
        kernel_interface_bundle,
    };
    let kernel_interface_bundle_json_bytes =
        serde_json::to_vec(&boundary.kernel_interface_bundle)?.len();
    let (boundary_path, boundary_json_bytes) = write_temp_json(name, &boundary)?;
    let output = Command::new(checker).arg(&boundary_path).output()?;
    let _ = fs::remove_file(&boundary_path);
    if !output.status.success() {
        return Err(anyhow!(
            "Lean runtime implementation confinement boundary validation failed for {}: {}",
            name,
            String::from_utf8_lossy(&output.stderr).trim()
        ));
    }
    Ok(json!({
        "scenario": name,
        "entrypoint": target.entrypoint,
        "setup_calls": setup.len(),
        "gas_used": trace.gas_used,
        "boundary_events": witness.boundary_schedule().len(),
        "kernel_witness": kernel_witness_summary(exact_kernel_witness.as_ref()),
        "runtime_kernel_refinement_witness": runtime_kernel_refinement_witness_summary(
            witness.runtime_kernel_refinement_witness(),
            exact_kernel_witness.as_ref(),
        ),
        "kernel_interface_bundle": {
            "expected_kernel_step_count": boundary
                .kernel_interface_bundle
                .expected_kernel_steps()
                .len(),
            "expected_public_object_universe":
                boundary.kernel_interface_bundle.expected_public_object_ids(),
            "expected_kernel_step_public_object_schedule":
                boundary
                    .kernel_interface_bundle
                    .expected_kernel_schedule()
                    .public_object_schedule(),
        },
        "implementation_interface_source_bytes":
            runtime_implementation_interface_source_bytes(implementation_interface),
        "kernel_interface_bundle_json_bytes": kernel_interface_bundle_json_bytes,
        "boundary_json_bytes": boundary_json_bytes,
        "shared_confidential_kernel_boundary_theorem_checked": true,
        "small_confidential_kernel_boundary_theorem_checked": true,
        "residual_helper_shell_boundary_theorem_checked": true,
        "slot_adapter_boundary_theorem_checked": true,
        "handwritten_runtime_public_only_theorem_checked": true,
        "runtime_kernel_confinement_projection_theorem_checked": true,
        "paper_end_to_end_confinement_with_public_only_handwritten_shell_theorem_checked":
            true,
        "paper_public_bridge_observer_refinement_theorem_checked": true,
        "lean_checker_kind": "runtime implementation confinement boundary",
        "lean_checker_input": "source-backed runtime implementation interface plus kernel-interface bundle",
        "lean_stdout": String::from_utf8_lossy(&output.stdout).trim(),
        "accepted": true,
    }))
}

