fn validate_runtime_implementation_kernel_meeting_confinement_boundary_case(
    name: &'static str,
    artifact: &CompiledArtifact,
    setup: &[CallSpec],
    target: &CallSpec,
    checker: &Path,
    implementation_interface: &ImportedRuntimeImplementationInterface,
) -> Result<JsonValue> {
    let trace = run_target_call(artifact, setup, target.entrypoint, target.args.clone())?;
    let runtime_witness = trace.runtime_refinement_witness()?;
    let exact_kernel_witness =
        exact_confidential_kernel_witness(&trace, artifact, target.entrypoint)?;
    if runtime_witness.kernel_witness() != exact_kernel_witness.as_ref() {
        return Err(anyhow!(
            "runtime refinement witness for {} does not preserve the exact kernel witness",
            name
        ));
    }
    let exact_runtime_kernel_refinement_witness =
        trace.exact_runtime_kernel_refinement_witness()?;
    if runtime_witness.runtime_kernel_refinement_witness()
        != Some(&exact_runtime_kernel_refinement_witness)
    {
        return Err(anyhow!(
            "runtime refinement witness for {} does not preserve the runtime phase witness",
            name
        ));
    }
    let runtime_kernel_machine_finish_witness =
        trace.exact_runtime_kernel_machine_finish_witness().map_err(|err| {
            anyhow!(
                "execution trace for {} did not expose an exact runtime kernel machine finish witness: {}",
                name,
                err
            )
        })?;
    let projected_finish_bundle = runtime_kernel_machine_finish_witness.projected_finish_bundle();
    let finish_bundle = trace.exact_runtime_kernel_finish_bundle().map_err(|err| {
        anyhow!(
            "execution trace for {} did not expose an exact runtime kernel finish bundle: {}",
            name,
            err
        )
    })?;
    if projected_finish_bundle != finish_bundle {
        return Err(anyhow!(
            "runtime implementation kernel meeting confinement boundary for {} does not preserve the exact runtime kernel finish bundle at the machine-finish boundary",
            name
        ));
    }
    let kernel_interface_bundle = trace.runtime_kernel_interface_bundle(artifact)?;
    if kernel_interface_bundle.kernel_witness() != exact_kernel_witness.as_ref().unwrap() {
        return Err(anyhow!(
            "runtime implementation kernel meeting confinement boundary for {} does not preserve the exact kernel witness at the reconstructed kernel-interface boundary",
            name
        ));
    }
    if kernel_interface_bundle.expected_kernel_steps()
        != kernel_interface_bundle.kernel_witness().kernel_steps()
    {
        return Err(anyhow!(
            "runtime implementation kernel meeting confinement boundary for {} does not preserve the exact expected kernel steps at the reconstructed kernel-interface boundary",
            name
        ));
    }
    if kernel_interface_bundle.expected_public_object_ids()
        != kernel_interface_bundle
            .kernel_witness()
            .expected_public_object_schedule()
            .as_deref()
            .unwrap_or(&[])
    {
        return Err(anyhow!(
            "runtime implementation kernel meeting confinement boundary for {} does not preserve the exact expected public object universe at the reconstructed kernel-interface boundary",
            name
        ));
    }
    if kernel_interface_bundle.expected_kernel_schedule()
        != &kernel_interface_bundle
            .kernel_witness()
            .emitted_kernel_schedule()
    {
        return Err(anyhow!(
            "runtime implementation kernel meeting confinement boundary for {} does not preserve the exact expected kernel schedule at the reconstructed kernel-interface boundary",
            name
        ));
    }
    let bundle = trace.runtime_confidential_core_kernel_finish_slot_bundle(artifact)?;
    let finish_shell_boundary_bundle = bundle.runtime_shell_boundary_bundle().map_err(|err| {
        anyhow!("reconstructing validated shell-boundary bundle for {name}: {err}")
    })?;
    if Some(finish_shell_boundary_bundle.kernel_witness()) != exact_kernel_witness.as_ref() {
        return Err(anyhow!(
            "runtime implementation kernel meeting confinement boundary for {} does not preserve the exact kernel witness at the finish-slot boundary",
            name
        ));
    }
    if trace.exact_runtime_kernel_refinement_witness()?
        != *finish_shell_boundary_bundle.runtime_kernel_refinement_witness()
    {
        return Err(anyhow!(
            "runtime implementation kernel meeting confinement boundary for {} does not preserve the runtime phase witness at the finish-slot boundary",
            name
        ));
    }
    let confidential_slot_program = bundle.confidential_slot_program();
    if confidential_slot_program
        .expected_runtime_step_witnesses()
        .as_ref()
        != finish_bundle.kernel_steps()
    {
        return Err(anyhow!(
            "runtime implementation kernel meeting confinement boundary for {} does not preserve the exact confidential slot schedule",
            name
        ));
    }
    let bundle_json = serde_json::to_value(&bundle)?;
    let projected_finish_bundle_json = serde_json::to_value(&projected_finish_bundle)?;
    if bundle_json["runtime_kernel_finish_bundle"] != projected_finish_bundle_json {
        return Err(anyhow!(
            "runtime implementation kernel meeting confinement boundary for {} does not preserve the exact meeting-point finish bundle in the emitted finish-slot artifact",
            name
        ));
    }
    let confidential_slot_program_entrypoint =
        confidential_slot_program.entrypoint_id.as_str().to_owned();
    let confidential_slot_program_param_count = confidential_slot_program.param_count;
    let confidential_slot_program_secret_arg_count = confidential_slot_program.secret_args.len();
    let confidential_slot_program_slot_count = confidential_slot_program.slot_count;
    let confidential_slot_program_statement_count = confidential_slot_program.body.len();
    let confidential_slot_program_expected_runtime_step_count =
        confidential_slot_program.expected_runtime_steps().len();
    let confidential_slot_program_statement_trace_count =
        confidential_slot_program.statement_trace().len();
    let matches_runtime_entrypoint = bundle.program_matches_runtime_entrypoint();
    let boundary = ImportedRuntimeImplementationKernelMeetingConfinementBoundary {
        implementation_interface: implementation_interface.clone(),
        runtime_kernel_machine_finish_witness,
        runtime_confidential_core_kernel_finish_slot_bundle: bundle,
    };
    let machine_finish_witness_json_bytes =
        serde_json::to_vec(&boundary.runtime_kernel_machine_finish_witness)?.len();
    let kernel_finish_slot_bundle_json_bytes =
        serde_json::to_vec(&boundary.runtime_confidential_core_kernel_finish_slot_bundle)?.len();
    let kernel_interface_bundle_json_bytes = serde_json::to_vec(&kernel_interface_bundle)?.len();
    let (boundary_path, boundary_json_bytes) = write_temp_json(name, &boundary)?;
    let output = Command::new(checker).arg(&boundary_path).output()?;
    if !output.status.success() {
        return Err(anyhow!(
            "Lean runtime implementation kernel meeting confinement boundary validation failed for {}: {} (artifact preserved at {})",
            name,
            String::from_utf8_lossy(&output.stderr).trim(),
            boundary_path.display()
        ));
    }
    let _ = fs::remove_file(&boundary_path);
    Ok(json!({
        "scenario": name,
        "entrypoint": target.entrypoint,
        "setup_calls": setup.len(),
        "gas_used": trace.gas_used,
        "boundary_events": runtime_witness.boundary_schedule().len(),
        "kernel_witness": kernel_witness_summary(exact_kernel_witness.as_ref()),
        "runtime_kernel_refinement_witness": runtime_kernel_refinement_witness_summary(
            runtime_witness.runtime_kernel_refinement_witness(),
            exact_kernel_witness.as_ref(),
        ),
        "runtime_kernel_machine_finish_witness": {
            "entrypoint_id": finish_bundle.entrypoint_id(),
            "expected_kernel_step_count": finish_bundle
                .expected_kernel_steps()
                .map_or(0, |steps| steps.len()),
            "emitted_kernel_step_count": finish_bundle.kernel_steps().len(),
            "expected_kernel_step_index":
                boundary.runtime_kernel_machine_finish_witness.expected_kernel_step_index(),
            "max_kernel_ops": boundary.runtime_kernel_machine_finish_witness.max_kernel_ops(),
            "max_runtime_phase_event_count":
                boundary.runtime_kernel_machine_finish_witness.max_runtime_phase_event_count(),
            "runtime_phase_prefix_event_count":
                finish_bundle.runtime_phase_events_before_finish().len(),
            "public_object_universe": finish_bundle.public_object_ids(),
            "resource_event_count": finish_bundle.resource_events().len(),
        },
        "kernel_finish_slot_bundle": {
            "entrypoint_id": confidential_slot_program_entrypoint,
            "param_count": confidential_slot_program_param_count,
            "secret_arg_count": confidential_slot_program_secret_arg_count,
            "slot_count": confidential_slot_program_slot_count,
            "statement_count": confidential_slot_program_statement_count,
            "expected_runtime_step_count":
                confidential_slot_program_expected_runtime_step_count,
            "statement_trace_count": confidential_slot_program_statement_trace_count,
            "matches_runtime_entrypoint": matches_runtime_entrypoint,
            "machine_finish_bundle_matches_emitted_finish_bundle": true,
        },
        "kernel_interface_bundle": {
            "expected_kernel_step_count": kernel_interface_bundle.expected_kernel_steps().len(),
            "expected_public_object_universe":
                kernel_interface_bundle.expected_public_object_ids(),
            "expected_kernel_step_public_object_schedule":
                kernel_interface_bundle
                    .expected_kernel_schedule()
                    .public_object_schedule(),
        },
        "implementation_interface_source_bytes":
            runtime_implementation_interface_source_bytes(implementation_interface),
        "machine_finish_witness_json_bytes": machine_finish_witness_json_bytes,
        "kernel_finish_slot_bundle_json_bytes": kernel_finish_slot_bundle_json_bytes,
        "kernel_interface_bundle_json_bytes": kernel_interface_bundle_json_bytes,
        "boundary_json_bytes": boundary_json_bytes,
        "shared_confidential_kernel_boundary_theorem_checked": true,
        "small_confidential_kernel_boundary_theorem_checked": true,
        "residual_helper_shell_boundary_theorem_checked": true,
        "slot_adapter_boundary_theorem_checked": true,
        "handwritten_runtime_public_only_theorem_checked": true,
        "runtime_implementation_confinement_projection_theorem_checked": true,
        "lean_checker_kind": "runtime implementation kernel meeting confinement boundary",
        "lean_checker_input":
            "source-backed runtime implementation interface plus machine-finish witness and emitted finish-slot bundle meeting at the native finish boundary before reconstructing the outer confinement boundary",
        "lean_stdout": String::from_utf8_lossy(&output.stdout).trim(),
        "paper_end_to_end_confinement_with_public_only_handwritten_shell_theorem_checked":
            true,
        "paper_public_bridge_observer_refinement_theorem_checked": true,
        "accepted": true,
    }))
}

