fn check_mixer_correctness(artifacts: &BenchArtifacts) -> Result<JsonValue> {
    let key = b32(9);
    let setup = vec![CallSpec {
        entrypoint: "deposit(bytes32,uint256)",
        args: vec![key.clone(), Value::Uint(5)],
    }];
    let target = CallSpec {
        entrypoint: "withdraw(bytes32,uint256)",
        args: vec![key.clone(), Value::Uint(2)],
    };
    let getters = vec![
        CallSpec {
            entrypoint: "balanceOf(bytes32)",
            args: vec![key.clone()],
        },
        CallSpec {
            entrypoint: "totalValue()",
            args: vec![],
        },
    ];
    let uo = run_scenario(&artifacts.uo, &setup, &target, &getters)?;
    let oram = run_scenario(
        artifacts
            .oram
            .as_ref()
            .ok_or_else(|| anyhow!("missing mixer oram"))?,
        &setup,
        &target,
        &getters,
    )?;
    let raw = run_optional_raw_scenario(&artifacts.raw, &setup, &target, &getters)?;
    let expected_return = Some(Value::Uint(2));
    let expected_getters = vec![Some(Value::Uint(3)), Some(Value::Uint(3))];
    Ok(json!({
        "benchmark": "ConfidentialMixer",
        "raw": optional_scenario_summary(&raw),
        "uo": scenario_summary(&uo),
        "oram": scenario_summary(&oram),
        "uo_matches_expected": scenario_matches(&uo, expected_return.as_ref(), &expected_getters),
        "oram_matches_expected": scenario_matches(&oram, expected_return.as_ref(), &expected_getters),
        "raw_equivalent_to_uo": optional_scenario_equivalent_to(&raw, &uo),
        "equivalent": scenario_matches(&uo, expected_return.as_ref(), &expected_getters)
            && scenario_matches(&oram, expected_return.as_ref(), &expected_getters),
    }))
}

fn check_erc20_correctness(artifacts: &BenchArtifacts) -> Result<JsonValue> {
    let alice = addr(0x11);
    let bob = addr(0x22);
    let carol = addr(0x33);
    let setup = vec![
        CallSpec {
            entrypoint: "mint(address,uint256)",
            args: vec![alice.clone(), Value::Uint(10)],
        },
        CallSpec {
            entrypoint: "approve(address,address,uint256)",
            args: vec![alice.clone(), bob.clone(), Value::Uint(4)],
        },
    ];
    let target = CallSpec {
        entrypoint: "transferFrom(address,address,address,uint256)",
        args: vec![alice.clone(), bob.clone(), carol.clone(), Value::Uint(3)],
    };
    let getters = vec![
        CallSpec {
            entrypoint: "balanceOf(address)",
            args: vec![alice.clone()],
        },
        CallSpec {
            entrypoint: "balanceOf(address)",
            args: vec![carol.clone()],
        },
        CallSpec {
            entrypoint: "allowanceOf(address,address)",
            args: vec![alice.clone(), bob.clone()],
        },
    ];
    let uo = run_scenario(&artifacts.uo, &setup, &target, &getters)?;
    let oram = run_scenario(
        artifacts
            .oram
            .as_ref()
            .ok_or_else(|| anyhow!("missing erc20 oram"))?,
        &setup,
        &target,
        &getters,
    )?;
    let raw = run_optional_raw_scenario(&artifacts.raw, &setup, &target, &getters)?;
    let expected_return = Some(Value::Uint(1));
    let expected_getters = vec![
        Some(Value::Uint(7)),
        Some(Value::Uint(3)),
        Some(Value::Uint(1)),
    ];
    Ok(json!({
        "benchmark": "ERC20Lite",
        "raw": optional_scenario_summary(&raw),
        "uo": scenario_summary(&uo),
        "oram": scenario_summary(&oram),
        "uo_matches_expected": scenario_matches(&uo, expected_return.as_ref(), &expected_getters),
        "oram_matches_expected": scenario_matches(&oram, expected_return.as_ref(), &expected_getters),
        "raw_equivalent_to_uo": optional_scenario_equivalent_to(&raw, &uo),
        "equivalent": scenario_matches(&uo, expected_return.as_ref(), &expected_getters)
            && scenario_matches(&oram, expected_return.as_ref(), &expected_getters),
    }))
}

